'use strict';
/* ============================================================================
   shipmodel.js — the player's starship, baked from a glTF asset.

   Embedded as base64 rather than loaded with fetch() on purpose: fetch is
   blocked under file://, and the whole game is meant to run by opening
   index.html directly.  The bake already applied the glTF node transform
   (Z-up to Y-up), recentred the hull on its bounding box and scaled it to
   11 m long, so the runtime just decodes and uploads.

   Layout: 8169 vertices of pos(3) nrm(3) uv(2) float32, then 20862 uint16 indices.
   ============================================================================ */

const SHIP_MODEL = {
  name: 'X-wing',
  vertexCount: 8169,
  indexCount: 20862,
  bounds: { lo: [-4.757, -1.070, -5.500], hi: [4.757, 1.070, 5.500] },
  engines: [[-1.26, -0.554, 5.5], [-1.297, 0.591, 5.5], [1.26, -0.554, 5.5], [1.297, 0.591, 5.5]],
  geo: '',
  tex: 'data:image/jpeg;base64,'
};
